te":"Official README documents a WSGI/Gunicorn server and a local Docker build."},{"slug":"fenrus","id":"d25faa6a-0ef7-44f4-ad3d-0a06896ffe57","existing":{"install_docs_url":"https://github.com/revenz/Fenrus#readme","docker_url":"https://github.com/revenz/Fenrus/blob/HEAD/Dockerfile","docker_image":null,"compose_url":null,"deployment_methods":["docker"],"docker_support":"official","compose_support":false},"proposed":{"install_docs_url":"https://github.com/revenz/Fenrus#readme","docker_url":"https://hub.docker.com/r/revenz/fenrus","docker_image":"revenz/fenrus:latest","compose_url":"https://github.com/revenz/Fenrus#readme","deployment_methods":["compose","docker","native"],"docker_support":"official","compose_support":true},"eligibility":"self_hostable","install_option_action":"populate","option_count":3,"verified_options":[{"method":"docker","label":"Docker image","url":"https://hub.docker.com/r/revenz/fenrus","source_url":"https://github.com/revenz/Fenrus#readme","image":"revenz/fenrus:latest","note":null,"support_level":"official","sort_order":10},{"method":"compose","label":"Docker Compose","url":"https://github.com/revenz/Fenrus#readme","source_url":"https://github.com/revenz/Fenrus#readme","image":"revenz/fenrus:latest","note":null,"support_level":"official","sort_order":20},{"method":"native","label":"Dotnet server","url":"https://github.com/revenz/Fenrus#readme","source_url":"https://github.com/revenz/Fenrus#readme","image":null,"note":"Run Fenrus.dll with the ASP.NET Core runtime.","support_level":"official","sort_order":30}],"sources":["https://github.com/revenz/Fenrus","https://github.com/revenz/Fenrus#readme","https://hub.docker.com/r/revenz/fenrus"],"technical_fact_status_additions":{"docker":{"status":"published","checked_at":"2026-09-30","confidence":"high","note":"Official upstream docs provide a Docker installation or build route.","source_urls":["https://github.com/revenz/Fenrus","https://github.com/revenz/Fenrus#readme","https://hub.docker.com/r/revenz/fenrus"]},"docker_image":{"status":"published","checked_at":"2026-09-30","confidence":"high","note":"Official upstream material identifies this Docker image.","source_urls":["https://github.com/revenz/Fenrus","https://github.com/revenz/Fenrus#readme","https://hub.docker.com/r/revenz/fenrus"]},"compose":{"status":"published","checked_at":"2026-09-30","confidence":"high","note":"Official upstream docs provide a Docker Compose deployment.","source_urls":["https://github.com/revenz/Fenrus","https://github.com/revenz/Fenrus#readme","https://hub.docker.com/r/revenz/fenrus"]}},"review_note":"Official README documents Docker, Compose and Dotnet install commands."}]$batch$::jsonb) AS review_rows(value)
  LOOP
    v_app_id := (v_app->>'id')::uuid;
    v_slug := v_app->>'slug';
    v_existing := v_app->'existing';
    v_proposed := v_app->'proposed';
    v_options := v_app->'verified_options';
    v_facts := coalesce(v_app->'technical_fact_status_additions', '{}'::jsonb);
    v_sources := ARRAY(
      SELECT DISTINCT source_url.value
      FROM jsonb_array_elements_text(v_app->'sources') AS source_url(value)
      ORDER BY 1
    );

    UPDATE public.self_host_apps AS a
    SET summary = coalesce(v_proposed->>'summary', a.summary),
        summary_source = coalesce(v_proposed->>'summary_source', a.summary_source),
        summary_confidence = coalesce(v_proposed->>'summary_confidence', a.summary_confidence),
        install_docs_url = v_proposed->>'install_docs_url',
        docker_url = v_proposed->>'docker_url',
        docker_image = v_proposed->>'docker_image',
        compose_url = v_proposed->>'compose_url',
        deployment_methods = ARRAY(SELECT jsonb_array_elements_text(v_proposed->'deployment_methods')),
        docker_support = v_proposed->>'docker_support',
        compose_support = (v_proposed->>'compose_support')::boolean,
        data_source_urls = ARRAY(
          SELECT DISTINCT source_url
          FROM unnest(coalesce(a.data_source_urls, ARRAY[]::text[]) || v_sources) AS collected(source_url)
          WHERE source_url IS NOT NULL
          ORDER BY source_url
        ),
        technical_fact_status = coalesce(a.technical_fact_status, '{}'::jsonb) || v_facts,
        updated_at = now()
    WHERE a.id = v_app_id
      AND a.slug = v_slug
      AND a.published IS NOT DISTINCT FROM TRUE
      AND a.self_hosting_status IS NOT DISTINCT FROM 'self_hostable'
      AND a.install_docs_url IS NOT DISTINCT FROM (v_existing->>'install_docs_url')
      AND a.docker_url IS NOT DISTINCT FROM (v_existing->>'docker_url')
      AND a.docker_image IS NOT DISTINCT FROM (v_existing->>'docker_image')
      AND a.compose_url IS NOT DISTINCT FROM (v_existing->>'compose_url')
      AND a.deployment_methods IS NOT DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(v_existing->'deployment_methods'))
      AND a.docker_support IS NOT DISTINCT FROM (v_existing->>'docker_support')
      AND a.compose_support IS NOT DISTINCT FROM (v_existing->>'compose_support')::boolean
      AND (NOT (v_existing ? 'summary') OR a.summary IS NOT DISTINCT FROM (v_existing->>'summary'))
      AND (NOT (v_existing ? 'summary_source') OR a.summary_source IS NOT DISTINCT FROM (v_existing->>'summary_source'))
      AND (NOT (v_existing ? 'summary_confidence') OR a.summary_confidence IS NOT DISTINCT FROM (v_existing->>'summary_confidence'))
      AND EXISTS (
        SELECT 1
        FROM public.self_host_app_install_options AS current_options
        WHERE current_options.app_id = a.id
          AND current_options.options IS NOT DISTINCT FROM '[]'::jsonb
      );
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Review guard failed for app %', v_slug;
    END IF;

    UPDATE public.self_host_app_install_options AS i
    SET options = v_options,
        source_urls = ARRAY(
          SELECT DISTINCT source_url
          FROM unnest(coalesce(i.source_urls, ARRAY[]::text[]) || v_sources) AS collected(source_url)
          WHERE source_url IS NOT NULL
          ORDER BY source_url
        ),
        checked_at = now(),
    docker_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'docker' ORDER BY 1),
    compose_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'compose' ORDER BY 1),
    truenas_scale_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'truenas_scale' ORDER BY 1),
    unraid_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'unraid' ORDER BY 1),
    umbrel_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'umbrel' ORDER BY 1),
    yunohost_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'yunohost' ORDER BY 1),
    casaos_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'casaos' ORDER BY 1),
    runtipi_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'runtipi' ORDER BY 1),
    cosmos_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'cosmos' ORDER BY 1),
    openmediavault_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'openmediavault' ORDER BY 1),
    synology_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'synology' ORDER BY 1),
    qnap_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'qnap' ORDER BY 1),
    proxmox_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'proxmox' ORDER BY 1),
    home_assistant_os_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'home_assistant_os' ORDER BY 1),
    kubernetes_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'kubernetes' ORDER BY 1),
    helm_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'helm' ORDER BY 1),
    native_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'native' ORDER BY 1),
    binary_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'binary' ORDER BY 1),
    package_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'package' ORDER BY 1),
    other_urls = ARRAY(SELECT DISTINCT route.value->>'url' FROM jsonb_array_elements(v_options) AS route(value) WHERE route.value->>'method' = 'other' ORDER BY 1),
    docker_images = ARRAY(SELECT DISTINCT route.value->>'image' FROM jsonb_array_elements(v_options) AS route(value) WHERE nullif(route.value->>'image','') IS NOT NULL ORDER BY 1),
        updated_at = now()
    FROM public.self_host_apps AS a
    WHERE i.app_id = a.id
      AND a.id = v_app_id
      AND a.slug = v_slug
      AND i.options IS NOT DISTINCT FROM '[]'::jsonb
    AND coalesce(cardinality(i.docker_urls),0) = 0
    AND coalesce(cardinality(i.compose_urls),0) = 0
    AND coalesce(cardinality(i.truenas_scale_urls),0) = 0
    AND coalesce(cardinality(i.unraid_urls),0) = 0
    AND coalesce(cardinality(i.umbrel_urls),0) = 0
    AND coalesce(cardinality(i.yunohost_urls),0) = 0
    AND coalesce(cardinality(i.casaos_urls),0) = 0
    AND coalesce(cardinality(i.runtipi_urls),0) = 0
    AND coalesce(cardinality(i.cosmos_urls),0) = 0
    AND coalesce(cardinality(i.openmediavault_urls),0) = 0
    AND coalesce(cardinality(i.synology_urls),0) = 0
    AND coalesce(cardinality(i.qnap_urls),0) = 0
    AND coalesce(cardinality(i.proxmox_urls),0) = 0
    AND coalesce(cardinality(i.home_assistant_os_urls),0) = 0
    AND coalesce(cardinality(i.kubernetes_urls),0) = 0
    AND coalesce(cardinality(i.helm_urls),0) = 0
    AND coalesce(cardinality(i.native_urls),0) = 0
    AND coalesce(cardinality(i.binary_urls),0) = 0
    AND coalesce(cardinality(i.package_urls),0) = 0
    AND coalesce(cardinality(i.other_urls),0) = 0
    AND coalesce(cardinality(i.docker_images),0) = 0;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Install-option guard failed for app %', v_slug;
    END IF;
  END LOOP;
END $$;

COMMIT;
